/// instructions that the bulk-copy translation layers on top of a wasm constant
/// length operand (e.g. widening the length to the pointer type, or scaling an
/// element count by the element size).
fn value_as_constant_i64(builder: &FunctionBuilder<'_>, value: ir::Value) -> Option<i64> {
    let inst = builder.func.dfg.value_def(value).inst()?;
    match builder.func.dfg.insts[inst] {
        ir::InstructionData::UnaryImm {
            opcode: ir::Opcode::Iconst,
            imm,
        } => Some(imm.bits()),
        ir::InstructionData::Unary {
            opcode: ir::Opcode::Uextend | ir::Opcode::Sextend | ir::Opcode::Ireduce,
            arg,
